import ApiService from"./api.min.js";export class OwnerReviewService{constructor(){this.api=new ApiService}async getReviewsForOwner(e){try{return(await this.api.get(`/api/owner-reviews/owner/${e}`)).data}catch(e){throw console.error("Error fetching owner reviews:",e),e}}async getReviewsByUser(e){try{return(await this.api.get(`/api/owner-reviews/user/${e}`)).data}catch(e){throw console.error("Error fetching user reviews:",e),e}}async createReview(e){try{return(await this.api.post("/api/owner-reviews",e)).data}catch(e){throw console.error("Error creating owner review:",e),e}}async updateReview(e,r){try{return(await this.api.put(`/api/owner-reviews/${e}`,r)).data}catch(e){throw console.error("Error updating owner review:",e),e}}async getReviewByAdoption(e){try{return(await this.api.get(`/api/owner-reviews/adoption/${e}`)).data}catch(e){throw console.error("Error fetching adoption review:",e),e}}async canUserReview(e,r){try{return(await this.api.get(`/api/owner-reviews/can-review/${e}/${r}`)).data}catch(e){throw console.error("Error checking review eligibility:",e),e}}formatReviewForDisplay(e){return{id:e.id,rating:e.rating,reviewText:e.review_text,communicationRating:e.communication_rating,petConditionRating:e.pet_condition_rating,processRating:e.process_rating,wouldRecommend:e.would_recommend,createdAt:new Date(e.created_at),reviewer:e.reviewer,animal:e.animal}}calculateReviewStatistics(e){if(!e||0===e.length)return{averageRating:0,totalReviews:0,recommendationPercentage:0,ratingDistribution:{5:0,4:0,3:0,2:0,1:0}};const r=e.length,t=e.reduce((e,r)=>e+r.rating,0)/r,i=e.filter(e=>e.would_recommend).length/r*100,a={5:0,4:0,3:0,2:0,1:0};return e.forEach(e=>{const r=Math.floor(e.rating);a.hasOwnProperty(r)&&a[r]++}),{averageRating:Math.round(10*t)/10,totalReviews:r,recommendationPercentage:Math.round(i),ratingDistribution:a}}}